// [Coreto TpNotetags] - Ganho de TP ao usar a skill
<Gain TP: +5>
<JS Post-Start Action>
  var thisSkillId = 47;
  if (user._embaloLastSkill === thisSkillId) {
    user._embaloCount = Math.min((user._embaloCount || 0) + 1, 3);
  } else {
    user._embaloCount = 1;
  }
  user._embaloLastSkill = thisSkillId;

  var tpBonus = (user._embaloCount - 1) * 4;
  if (tpBonus > 0) {
    var tpFinal = Math.round(tpBonus * user.tcr);
    user.gainTp(tpFinal);
  }
  user.refresh();

</JS Post-Start Action>
<JS ATB After Gauge>
// Fluxo Continuo: Momentum acumulado aumenta velocidade do Socao
// 0 TP = speed 0, 100 TP = speed 1000 (rate 0.50)
if (user.states().includes($dataStates[65])) {
  rate = Math.min(user.tp * 0.005, 0.50);
}
</JS ATB After Gauge>

